"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[98665],{98665:function(e){e.exports=JSON.parse('{"content":"\\n<center>\\n<RestaurantCard\\n  cover=\\"/assets/snippets/location/d0cf66a79c7ae9c0762180add1cff359.jpg\\"\\n  title=\\"Ca Fe In Melbourne\\"\\n  cuisine=\\"Cafe\\"\\n  address=\\"575 Bourke St, Melbourne VIC 3000 Australia\\"\\n  rating=4\\n  tags=\\"cafe\\"\\n/>\\n</center>\\n\\n## Review\\nIt was the <mark>first cafe</mark> I visited right after arriving in Australia.  \\nIt was my first coffee on unfamiliar Melbourne soil, and it turned out to be the best coffee of my entire trip — perfectly suited to my taste.  \\n\\nThe ```nerdy charm``` of the owner who took my order was surprisingly right up my alley.  \\nSeeing the ```periodic table T-shirt``` the owner was wearing and the cafe name — a combination of chemical element symbols (Ca, Fe, In) — I was convinced he had an engineering background.  \\n\\nHe was friendly yet clearly took great pride in his coffee.  \\nThanks to him, my very first impression of Australia remained a warm and wonderful memory.  \\n\\n## Pictures\\n<pictures>\\n<img src=\\"/assets/snippets/location/d0cf66a79c7ae9c0762180add1cff359.jpg\\" style=\\"max-width: 100%; height: auto; object-fit: contain;\\" alt=\\"Ca Fe In Melbourne\\">\\n<img src=\\"/assets/snippets/location/6b805d62009e222a448953cd141c6236.jpg\\" style=\\"max-width: 100%; height: auto; object-fit: contain;\\" alt=\\"Ca Fe In Melbourne\\">\\n<img src=\\"/assets/snippets/location/a44bba3e4e46db08dd300975b969baec.jpg\\" style=\\"max-width: 100%; height: auto; object-fit: contain;\\" alt=\\"Ca Fe In Melbourne\\">\\n</pictures>\\n"}')}}]);